#!/usr/bin/env bash
# AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following design
# decisions made by the author. See ATTRIBUTION.md for details.
# Step 0 items 5, 8, 9 (P1 v0.3): fetch pinned assets. Run from the repo root with Git Bash.
# Kokoro English voices, Piper en_US-libritts-high, whisper-base (HF, pinned revisions); DEMAND 16 kHz (Zenodo
# 1227121, md5-checked); RIRS_NOISES (OpenSLR 28, EU mirror). Each download goes to its own directory under data/.
set -u
PY="$(pwd)/.venv-gpu/Scripts/python.exe"

$PY - <<'PYEOF'
from huggingface_hub import hf_hub_download, snapshot_download
voices = ["af_heart", "af_alloy", "af_aoede", "af_bella", "af_jessica", "af_kore", "af_nicole", "af_nova", "af_river",
          "af_sarah", "af_sky", "am_adam", "am_echo", "am_eric", "am_fenrir", "am_liam", "am_michael", "am_onyx",
          "am_puck", "am_santa", "bf_alice", "bf_emma", "bf_isabella", "bf_lily", "bm_daniel", "bm_fable",
          "bm_george", "bm_lewis"]
for v in voices:
    hf_hub_download("hexgrad/Kokoro-82M", f"voices/{v}.pt", revision="f3ff3571791e39611d31c381e3a41a3af07b4987")
print("kokoro voices", len(voices))
for f in ["en/en_US/libritts/high/en_US-libritts-high.onnx", "en/en_US/libritts/high/en_US-libritts-high.onnx.json",
          "en/en_US/libritts/high/MODEL_CARD"]:
    hf_hub_download("rhasspy/piper-voices", f, revision="6b9cfaacb4fb2e02a9621227e3c1a48bec9710c3",
                    local_dir="data/models_dl/piper_libritts_high_6b9cfaa")
print("piper done")
p = snapshot_download("openai/whisper-base", allow_patterns=["*.json", "*.safetensors", "*.txt", "*.model"])
print("whisper-base", p)
PYEOF

mkdir -p data/demand_dl && cd data/demand_dl
$PY -c "
import json, urllib.request
r = json.loads(urllib.request.urlopen('https://zenodo.org/api/records/1227121', timeout=60).read())
open('files.tsv', 'w').write(''.join(f\"{f['key']}\t{f['checksum'].split(':')[1]}\n\" for f in r['files'] if '16k' in f['key']))
"
while IFS=$'\t' read -r name md5; do
  for try in 1 2 3; do
    curl -sL --retry 5 -C - -o "$name" "https://zenodo.org/records/1227121/files/$name?download=1" && break
  done
  echo "$md5  $name" | md5sum -c - || echo "MD5 MISMATCH $name"
done < files.tsv
cd ../..

mkdir -p data/rirs_dl && curl -sL --retry 5 -C - -o data/rirs_dl/rirs_noises.zip https://openslr.elda.org/resources/28/rirs_noises.zip
md5sum data/rirs_dl/rirs_noises.zip
ls -la data/rirs_dl data/demand_dl | head -30
echo ALL DONE
